INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1292509-coe301', 'stk-sultan11', 'COE 301', 'info', '{"desc": "السلام عليكم .\n\nالمقرر تتعلم عن طريقة لغة الـ Assembly و تتعلم عن محتويات المعالج نفسه و كيف يتم تقسيم المعلومات داخله . بتعرف أكثر عن المسارات الخاصة بنقل البيانات داخل الدارات الكهربائية Busses و بتتعلم بروتوكولات تهتمّ بنقل الداتا على أكثر من طريقة . أيضاً بتتعلم بعض الأمور بالنسبة لنوع البيانات Word , Double word , Half word … etc . أيضاً بتتعلم فوائد ما يسمّي بالـ Registers و أن فيه بعضها تستخدم بشكل عامّ من قبل البرمجيات و فيه بعضها مخصصّة الاستخدام . نهايةً في اللاب بتبني CPU عن طريق برنامج للمحاكاة أسمه LogiSim .\n\nجودة المقرر بشكل عام : ممتاز جداً . أخذته مع الدكتور أيمن الملح لما كان باسم COE 205 . كورس ممتع و عميق\n\nالمواضيع التي يغطيها المقرر : Computer Architichture . معمارية الحاسوب و المعالج . أيضاً لغة البرمجة Assembly . ما أعرف لو حتغطّوا Mips ولا MASM . أنا أخذت الكورس و كانت MASM IA 32\n\nالكتاب المستخدم للمقرر : كان متوسط . إعتمدت ع السلايدز و مصادر الانترنت أكثر منه. لكن شرحه مفهوم\n\nالأسئلة والأمثلة المستخدمة في المقرر: الدكتور أيمن مشهور أن شرحة ممتاز و أسئلته من نوتته.\n\nمدى فائدته في الناحية التطبيقية: مفيد جداً للمهتمين بالـ HARDWARE خصوصاً . مفيد أيضاً للمهتمين للـ Process performance لأنك تقدر تكتب أكواد عالية الكفاءة .\n\nبالتوفيق لمهندسيننا القادمين 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-301-computer-organization/120814/2", "user": "Sultan11", "ts": 1385173350000, "tid": 120814, "pn": 2}}', 1385173350000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1484133-coe301', 'stk-krooom', 'COE 301', 'info', '{"desc": "162\nالمقرر من اهم المواد في مجالات الكمبيوتر بشكل عام\nتتعلم عن طريقة لغة الـ Assembly و تتعلم عن محتويات المعالج نفسه و كيف يتم تقسيم المعلومات داخله . بتعرف أكثر عن المسارات الخاصة بنقل البيانات داخل الدارات الكهربائية Busses و بتتعلم بروتوكولات تهتمّ بنقل الداتا على أكثر من طريقة . أيضاً بتتعلم بعض الأمور بالنسبة لنوع البيانات Word , Double word , Half word … etc . أيضاً بتتعلم فوائد ما يسمّي بالـ Registers و أن فيه بعضها تستخدم بشكل عامّ من قبل البرمجيات و فيه بعضها مخصصّة الاستخدام .\nنهايةً في اللاب بتبني CPU باوامر محددة يختاروها الدكاترة عن طريق برنامج للمحاكاة أسمه LogiSim\n\nجودة المقرر بشكل عام : ممتاز جداً . و مهم جدا\n\nالمواضيع التي يغطيها المقرر : Computer Architichture . معمارية الحاسوب و المعالج . أيضاً لغة البرمجة Assembly . اوامر Mips\n\nالكتاب المستخدم للمقرر :\nسلايدات ايمن الميلح تكفي\n\nمدى فائدته في الناحية التطبيقية: مفيد جداً للمهتمين بالـ HARDWARE خصوصاً . مفيد أيضاً للمهتمين للـ Process performance لأنك تقدر تكتب أكواد عالية الكفاءة . و حلوة انه يغطي اسيمبلي وبعدين يشرح لك كيف يتنفذوا بالهاردوير خطوة خطوة\n\nيعني تعرف كيف الكمبيوتر يشتغل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-301-computer-organization/120814/3", "user": "Krooom", "ts": 1512204601000, "tid": 120814, "pn": 3}}', 1512204601000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ma7mud-coe301', 'stk-ma7mud', 'COE 301', 'doc', '{"docs": [{"id": "stk-dr-f98318", "n": "Dr. Muhamed F. Mudawar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "COE 301 TERM181\n\nالتحضير : يحضر أول ما تبدأ المحاضرة، ويرجع يحضر في النهاية، ما يحاسب على التأخير، كان في احد الطلاب “للأسف” يجي في نص المحاضرة مع ذلك كان دايما يحضره، اخر الفصل قال ما راح اخصم على الغياب بس أحضر عشان سياسة الجامعة\n\nطريقة الشرح : يشرح من سلايداته، افضل سلايدات ممكن تشوفها، ممتازة جدا جدا ومتعوب عليها وواضحة جدا ومفهومة. الشرح ممتاز جدا. المشكلة الوحيدة ان احيانا الدكتور يكرر بعض الأشياء البسيطة أو يكرر في الشرح وياخذ وقت على اشياء ما تستاهل وتصير المحاضرة مملة ونتأخر في المنهج. ما خلصنا الا اخر يوم وما أعطانا كلاس off عشان الاختبار. بس عموما الشرح ماعليه غبار\n\nالكويزات : متوسطة، أسئلة مشابه للاختبارات، اتوقع حذف اسوأ كويز او اثنين.\nالمياجر: سهل نوعا ما\n\nالفاينلات :كان اصعب من المياجر\n\nالقريد النهائي: A+\n\nالصوت: ممتاز وواضح ولهجه ممتازة جدا\nإضافات : الدكتور أسطوري وما يتفوف، الشرح ممتاز جدا وواضح، السلايدات ممتازة، التحضير متساهل جدا، ومتعاون جدا وتصحيح الدكتور جدا ممتاز، مستحيل يخصم درجة السؤال اذا غلطت يحاول يعطيك درجة على أي شي كاتبه ويحاول يفهم جوابك عشان يعطيك عليه درجة حتى لو غلط!\nالدكتور ينزل الدرجات لكل شي على البلاكبورد ودايما يحط الأفرج لكل شي عشان تعرف كيف مستواك ماشي، حركة مفيدة جدا افرج الكوس كان 80 مع ان المادة ماهي سهلة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504409-coe301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhamed-f-mudawar/98318/15", "user": "Ma7mud", "ts": 1546424390000, "tid": 98318, "pn": 15}}]}', 1546424390000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ali19-coe301', 'stk-ali19', 'COE 301', 'doc', '{"docs": [{"id": "stk-dr-f98318", "n": "Dr. Muhamed F. Mudawar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "COE 301 - 181\nالتحضير :\nيحضر مرة في البداية، وفي نهاية المحاضرة يحضر المتأخرين. ما يحاسب على التأخير ولو آخر ربع ساعة لكن ما يفضل الطلاب المتأخرين.\nطريقة الشرح :\nيمشي على السلايدات، بشكل عام السلايدات جداً واضحة خصوصاً في ال٣٠١ و تقريباً ممكن الطالب يفهم أغلب المواضيع بنفسه. لكن شرح دكتور مدور يخليك تفهم الكونسبت بشكل ممتاز وتصير أوضح خصوصاً لما يعطي أمثلة.\nالشي الموحيد اللي ممكن يكون سلبي التكرار وخصوصاً لما الدكتور يشرح أي جدول يشرح جميع الاشياء في الجدول حتى لو كانت واضحة، وهالشي ممكن هو اللي خلانا نتأخر نسبياً (خلصنا المنهج آخر يوم)!\nالكويزات :\nمتوسطة بشكل عام، تغطي النقاط المهمة و اللي يركز عليها في الشرح + تشبه الاولد اقزامز نسبياً.\nالمياجر:\nاغلب الأسئلة تشبه الكويزات و الأولد اقزامز.\nالفاينلات :\nأصعب من المدترم، فيه بعض الأفكار الجديدة.\nالقريد النهائي: A+\nالصوت:\nجداً واضح.\nإضافات :\n\n١- الدكتور متعاون جداً في التصحيح، غالباً بيعطيك درجة فوق اللي تتوقعها لو بينت انك فاهم الأساسيات في الحل.\n٢- من أفضل الدكاترة في الشرح في المكتب.\n٣- الدكتور جداً بشوش و الترم معاه حلو و أنصح تنزل عنده اي كورس اذا موجود.\n٤- يغير أوقات الكويزات و الواجبات اذا كان لاطلاب عندهم زحمة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1507206-coe301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhamed-f-mudawar/98318/16", "user": "Ali19", "ts": 1552513624000, "tid": 98318, "pn": 16}}]}', 1552513624000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-breaktheunbreakable-coe301', 'stk-breaktheunbreakable', 'COE 301', 'doc', '{"docs": [{"id": "stk-dr-f98318", "n": "Dr. Muhamed F. Mudawar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "دكتور مدور أسطورة قسم الكمبيوتر وما أدراك من هو 🙂\n\nCOE 301 TERM181\n\nالتحضير : مثل ما قالوا الشباب فوق\n\nطريقة الشرح : ممتاز جدا ومن السلايدات حقته اللي تاعب عليها، وأحسن سلايدات ممكن تشوفها. اللي ما عجبني فيه فقط كان بطيء وبعض الأشياء يشرحها كثير لدرجة تنبت في مخك\n\nالكويزات : متوسطة بعضها مائل للسهولة وبعضها للصعوبة. أغلبها من مياجره أو أسئلته في صفحته\nالمدتيرم: سهل ومشابه للمدترم السابقة إذا تدربت عليها جيدًا.\nالفاينلات: فيه أفكار جديدة وأشياء حلوة شلنجنغ D:. أقدر أقول متوسط مائل للصعوبة…\nالقريد النهائي: A+\nالصوت: ممتاز ومتقن\nإضافات : نزل عنده أي مادة متصلة بالكمبيوتر أركتكشر.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1510173-coe301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhamed-f-mudawar/98318/17", "user": "BreakTheUnbreakable", "ts": 1558772283000, "tid": 98318, "pn": 17}}]}', 1558772283000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ad0rs-coe301', 'stk-ad0rs', 'COE 301', 'doc', '{"docs": [{"id": "stk-dr-f98324", "n": "Dr. Aiman H. El-Maleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "coe301-t151\n\nالتحضير :\nبداية الكلاس وماعنده ليت وماينقص عالغيابات\nطريقة الشرح :\nمن سلايدات د.مدور\nالكويزات :\nمن الاولد اقزامز وهو ينبهك من بدري ان الكويزات راح تجي من الاولد اقزامز\nالمياجر:\nكومون (هو يحط تقريبا 40% من أسئلة المياجر والباقي د.مايز)\nالفاينلات :\nنفس المياجر\nالقريد النهائي:\nB\nالصوت:\nواضح\nإضافات :\nباقي دكاترة ال coe اللي درست عندهم يعطوا قريدات أحسن\nهذه قريداته ل151 في المرفقات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1440100-coe301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-aiman-h-el-maleh/98324/17", "user": "ad0rs", "ts": 1453410650000, "tid": 98324, "pn": 17}}, {"id": "stk-dr-f98334", "n": "Dr. Kamel Chenaoua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Coe301 lab t151\n\nالتحضير :\nآخر اللاب ومتساهل جدا\nطريقة الشرح :\nنشتغل عالتاسكات وأحيانا يشرح عالسبورة اذا في نقطة يحتاج لها فهم\nالقريد النهائي:\nB+\nالصوت:\nواضح\nإضافات :\nعيب الدكتور انه فوضوي يعني مانعرف ايش يبغى بالضبط\nيعطينا تاسك ولما نخلصه يقول كان تسووا الشي الفلاني أول\nباختصار ماتقدر تتجهز للاب من بدري لأنك ماتعرف إيش راح يطلب منك للحظة الأخيرة\n+\nهو طفشان من اللاب ويقول انه ماراح ينزله بعد كذا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1440102-coe301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-kamel-chenaoua/98334/9", "user": "ad0rs", "ts": 1453410973000, "tid": 98334, "pn": 9}}]}', 1453410650000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-coe301', 'stk-guest', 'COE 301', 'doc', '{"docs": [{"id": "stk-dr-f174789", "n": "Dr. Saleh Alsaleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "نزلت عنده مادة COE 301 ترم 182\nالتحضير: متشدد وطريفته غريبة نوعا ما، عنده اكسل شيت فيها يخصم عليك بمدة التأخير بالدقائق\nطريقة الشرح : بداية اللاب يشرح كل شي مهم بعدها يعطيك التاسكات المطلوبة وتبدا الحل وهو يراقب ويساعدك اذا علقت في شي. اكثر همه انك فاهم وهو بيساعدك في الحل\nالكويزات : يختبر ثلاث او اربعة لاب كويز. متوسطة الى سهلة الا كويز واحد كان صعب لان المتيريال نفسه صعب مو من المدرس\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح بس خفيف، لازم تكون فبداية الكلاس عشان تسمعه 100%\nإضافات : الاستاذ جدا متساعد وتقدر تكلمه متى ما احتجته، حتى في مواضيع خارج الكورس، حتى لو مساعدة في كورس ثاني\nيطلب منك ريبورت على كل لاب ولازم في objectives introduction tasks and conclusion ويصحح كل اللي كتبته، العادة ما يخصم الا على التاسكات والباقي بس عشان تتعود على الريبورتات.\nفي نهاية اللاب وقت البروجكت يحشرك تحشير مب طبيعي عشان يتأكد انك فاهم، بس اتذكر انه كان متساعد في الدرجات.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526762-coe301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saleh-alsaleh/174789/2", "user": "Guest", "ts": 1606022855000, "tid": 174789, "pn": 2}}, {"id": "stk-dr-f98324", "n": "Dr. Aiman H. El-Maleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "COE 301 Term 182\nCOE 306 Term 191\nالتحضير : ما يهتم له، مرة حضرت اخر الدقايق وحضرني ولا يخصم على الغياب\nبس في بونص 0.5 نهاية الترم للي ما غابو\nيقول انه ما خصم لان اذا غبت انت عاقبت نفسك وراحت عليك معلومات فالكلاس عشان كذا ما يحتاج يعاقبك على الغياب\nاذا غبت كثير ورا بعض يرسل لك ايميل يقول لك تراك غبت كثير وراحت عليك معلومات مهمة وينصحك تروح له الاوفيس اذا احتجت شي\nطريقة الشرح : ممتاز، اتعب وانا اقول انه ممتاز.\nيبسط لك الكورس ويفهمك عدل، كل اللي تحتاجه انك تركز معاه وبتشوف كيف ان شرحه ممتاز\nالكويزات : اكمل الفراغ، كلها من كويزات واختبارات قديمة، سهلة جدا\nالمياجر: مو ميجر، مد نفس الكويزات بس اختبار اكبر\nالفاينلات : نفس المد\nالقريد النهائي: A+\nالصوت: واصح جدا\nإضافات : يشجع على المشاركة في الكلاس ويعطي بونص 0.5 على كل مشاركة، تقدر تجمع لك بونص الى 3 درجات من الكورس\nالعادة توزيع الدرجات A+ 90 وتنزل 5 لكل قريد، وعنده ابقريد اذا احتجت نص على القريد الجاي\nالدكتور مكتبة من العلوم، اي شي تحتاجه متعلق بالحاسب يعرفه\nمتساعد جدا ويرحب فيك في الاوفيس طول الوقت\nلو شفت اسمه في كورس، لا تنزل الا عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526763-coe301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-aiman-h-el-maleh/98324/24", "user": "Guest", "ts": 1606023697000, "tid": 98324, "pn": 24}}]}', 1606022855000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alwalid1-coe301', 'stk-alwalid1', 'COE 301', 'doc', '{"docs": [{"id": "stk-dr-f185278", "n": "Dr. Khalid Al-Hawaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني COE301 T241\nالتحضير : اول كم يوم كان يحضر بعدين صار مايحضر. يقول بغيابك انت قاعد تضر نفسك\nطريقة الشرح : افضل دكتور درست عنده. يوصلك المعلومة بشكل واضح. ما احتجت ابحث عن مصادر ثانية. فيه مشكلة انه مايشارك سلايداته\nالكويزات : كويزاته صعبة وفعلا تختبر فهمك. اشوفها افضل من انه يعطيك اسئلة تحجيرية مامنها فائدة.\nالقريد النهائي: A+\nالصوت: واضح جدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1539810-coe301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-hawaj/185278/2", "user": "Alwalid1", "ts": 1750603679455, "tid": 185278, "pn": 2}}]}', 1750603679455, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
